public final class DStorageAdaptersGameTests {
    static StorageAccessPolicy policy(net.minecraft.server.level.ServerLevel level,StorageRegistry registry,StorageIncarnationAdapter identities,java.util.function.BooleanSupplier allowed){
        return new StorageAccessPolicy(registry::snapshot,(scope,ids)->new OrganizationMembershipPort.View(scope,0,Map.of()),(scope,owner)->new StorageAccessPolicy.Control(scope,owner,0,true,false,Set.of()),(scope,row,op,tick)->new StorageAccessPolicy.Protection(scope,row.id(),op,0,tick,row.generation(),allowed.getAsBoolean() && identities.resolve(row.id()).isPresent()?StorageAccessPolicy.Result.ALLOW:StorageAccessPolicy.Result.DENY),level::getGameTime);
    }
    @GameTest(maxTicks=5000)
    public void nativeSingleDoubleBarrelCapacityAndFailClosedEligibility(GameTestHelper h){
        DNativeScene.open(h,"D05-GT01",false,s->{var policy=policy(s.level,s.registry,s.adapter,s.allow::get);var reader=new MinecraftStorageAdapter(s.level,s.adapter,s.registry::snapshot,policy,(scope,id,op,pos)->s.allow.get());var scope=new StorageAccessPolicy.Scope(s.world,UUID.randomUUID(),DNativeScene.PRINCIPAL,null);var publicGrant=new Grant(new Owner(OwnerKind.PUBLIC,null),Set.of(Permission.INSPECT,Permission.DEPOSIT,Permission.WITHDRAW));
            BlockPos single=h.absolutePos(new BlockPos(2,2,2)),pair=h.absolutePos(new BlockPos(6,2,2)),barrel=h.absolutePos(new BlockPos(10,2,2));s.level.setBlockAndUpdate(single,Blocks.CHEST.defaultBlockState());s.level.setBlock(pair,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.LEFT),2);s.level.setBlock(pair.east(),Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.RIGHT),2);s.level.setBlockAndUpdate(barrel,Blocks.BARREL.defaultBlockState());
            s.registerShared(single,SINGLE,"single",List.of(publicGrant),id->s.bind(id,single,true,b->{
                var c=(ChestBlockEntity)s.be(single);c.setItem(0,new ItemStack(Items.OAK_PLANKS,32));c.setItem(1,new ItemStack(Items.OAK_PLANKS,64));c.setItem(2,new ItemStack(Items.WOODEN_PICKAXE));
                check(h,s,reader,scope,id,"SINGLE",1568,96,27);c.setItem(0,new ItemStack(Items.OAK_PLANKS,64));check(h,s,reader,scope,id,"SINGLE_CHANGED",1536,128,27);
                c.applyComponents(DataComponentMap.builder().set(DataComponents.LOCK,new net.minecraft.world.LockCode(net.minecraft.advancements.predicates.ItemPredicate.Builder.item().of(s.level.registryAccess().lookupOrThrow(Registries.ITEM),Items.DIAMOND).build())).build(),DataComponentPatch.EMPTY);
                h.assertTrue(c.isLocked(),"lock fixture not actual");h.assertTrue(reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)).refusal()==StorageCapabilities.Refusal.LOCKED,"locked treated as empty");frame(s,"LOCKED",id,reader.observe(scope,id),reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)));c.applyComponents(DataComponentMap.builder().set(DataComponents.LOCK,net.minecraft.world.LockCode.NO_LOCK).build(),DataComponentPatch.EMPTY);
                c.setLootTable(ResourceKey.create(Registries.LOOT_TABLE,Identifier.parse("minecraft:chests/simple_dungeon")));h.assertTrue(reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)).refusal()==StorageCapabilities.Refusal.LOOT_TABLE,"unresolved loot unpacked");h.assertTrue(c.getLootTable()!=null,"observation generated loot");frame(s,"LOOT",id,reader.observe(scope,id),reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)));c.setLootTable(null);
                var modified=new ItemStack(Items.OAK_PLANKS);modified.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("not default"));h.assertTrue(reader.check(scope,id,Permission.DEPOSIT,modified).refusal()==StorageCapabilities.Refusal.COMPONENTS,"modified stack accepted");h.assertTrue(reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.SHULKER_BOX)).refusal()==StorageCapabilities.Refusal.COMPONENTS,"container item accepted");
                s.registerShared(pair,DOUBLE,"double",List.of(publicGrant),two->s.bind(two,pair,true,bb->{var left=(ChestBlockEntity)s.be(pair);var right=(ChestBlockEntity)s.be(pair.east());left.setItem(0,new ItemStack(Items.OAK_PLANKS,32));left.setItem(1,new ItemStack(Items.STONE,64));right.setItem(0,new ItemStack(Items.OAK_PLANKS,64));right.setItem(26,new ItemStack(Items.OAK_PLANKS,1));check(h,s,reader,scope,two,"DOUBLE",3295,97,54);
                    s.registerShared(barrel,BARREL,"barrel",List.of(publicGrant),three->s.bind(three,barrel,true,bc->{var box=(BarrelBlockEntity)s.be(barrel);box.setItem(0,new ItemStack(Items.OAK_PLANKS,63));box.setItem(1,new ItemStack(Items.STONE,64));check(h,s,reader,scope,three,"BARREL",1601,63,27);
                        var other=new StorageAccessPolicy.Scope(s.world,scope.domain(),UUID.randomUUID(),null);h.assertTrue(reader.observe(other,UUID.randomUUID())==StorageSnapshot.Unavailable.INSTANCE,"missing leaked");s.allow.set(false);h.assertTrue(reader.observe(scope,id)==StorageSnapshot.Unavailable.INSTANCE,"protection denied observation leaked");s.allow.set(true);
                        benchmark(h,s,reader,scope,two);BlockPos far=single.offset(100000,0,100000);h.assertTrue(!s.level.hasChunkAt(far),"unloaded control unexpectedly loaded");var chestRefusal=ChestStorageAdapter.refusal(s.level,far);var barrelRefusal=BarrelStorageAdapter.refusal(s.level,far);h.assertTrue(chestRefusal==StorageCapabilities.Refusal.UNLOADED && barrelRefusal==StorageCapabilities.Refusal.UNLOADED && !s.level.hasChunkAt(far),"unloaded type probe forced a chunk or treated it as empty");write(s.evidence.resolve("adapter-controls.json"),Map.of("unloaded_position",List.of(far.getX(),far.getY(),far.getZ()),"loaded_before",false,"loaded_after",s.level.hasChunkAt(far),"chest_refusal",chestRefusal,"barrel_refusal",barrelRefusal));BlockPos trapped=h.absolutePos(new BlockPos(14,2,2));s.level.setBlockAndUpdate(trapped,Blocks.TRAPPED_CHEST.defaultBlockState());h.assertTrue(s.level.getBlockEntity(trapped) instanceof ChestBlockEntity,"trapped inheritance control absent");h.assertTrue(ChestStorageAdapter.refusal(s.level,trapped)==StorageCapabilities.Refusal.UNSUPPORTED,"trapped subclass slipped in");write(s.evidence.resolve("adapter-type-controls.json"),Map.of("block","minecraft:trapped_chest","native_class",s.level.getBlockEntity(trapped).getClass().getName(),"chest_instance",s.level.getBlockEntity(trapped) instanceof ChestBlockEntity,"refusal",ChestStorageAdapter.refusal(s.level,trapped)));
                        s.level.setBlockAndUpdate(pair.east(),Blocks.AIR.defaultBlockState());h.assertTrue(!reader.check(scope,two,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)).eligible(),"incomplete double topology accepted");frame(s,"TOPOLOGY_INVALID",two,reader.observe(scope,two),reader.check(scope,two,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS)));s.finish();
                    }));
                }));
            }));
        });
    }
    private static void benchmark(GameTestHelper h,DNativeScene s,MinecraftStorageAdapter reader,StorageAccessPolicy.Scope scope,UUID id){long[] samples=new long[200];for(int i=0;i<250;i++){long start=System.nanoTime();var check=reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS));long elapsed=System.nanoTime()-start;h.assertTrue(check.eligible(),"benchmark lost current native binding");if(i>=50)samples[i-50]=elapsed;}Arrays.sort(samples);var values=new TreeMap<String,Object>();values.put("warmup",50);values.put("samples",samples);values.put("p50_ns",samples[99]);values.put("p95_ns",samples[189]);values.put("p99_ns",samples[197]);values.put("max_ns",samples[199]);values.put("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());values.put("slots_per_operation",54);values.put("scheduled_tick_tasks",0);write(s.evidence.resolve("adapter-performance.json"),values);}
    private static void write(Path path,Object value){try{Files.writeString(path,new com.google.gson.GsonBuilder().serializeNulls().create().toJson(value)+"\n");try(var channel=java.nio.channels.FileChannel.open(path,StandardOpenOption.WRITE)){channel.force(true);}}catch(Exception error){throw new RuntimeException(error);}}
    private static void check(GameTestHelper h,DNativeScene s,MinecraftStorageAdapter reader,StorageAccessPolicy.Scope scope,UUID id,String event,int capacity,int count,int slots){var check=reader.check(scope,id,Permission.DEPOSIT,new ItemStack(Items.OAK_PLANKS));var visible=reader.observe(scope,id);h.assertTrue(check.eligible() && check.insertionCapacity()==capacity && check.matchingItems()==0 && reader.check(scope,id,Permission.WITHDRAW,new ItemStack(Items.OAK_PLANKS)).matchingItems()==count,"actual native capacity/count "+event+" "+check);h.assertTrue(visible instanceof StorageSnapshot.Visible v && v.slots().size()==slots,"actual native slots "+event);frame(s,event,id,visible,check);}
    private static void frame(DNativeScene s,String event,UUID id,StorageSnapshot snapshot,MinecraftStorageAdapter.Check check){var row=new TreeMap<String,Object>();row.put("case","D05-GT01");row.put("event",event);row.put("world",s.world);row.put("storage",id);row.put("tick",s.level.getGameTime());row.put("snapshot",snapshot instanceof StorageSnapshot.Visible?snapshot:null);row.put("check",check);var binding=StorageBindingRules.Binding.from(s.registry.snapshot().bindings().get(id));row.put("binding",binding.wire().body());var nativeRows=new ArrayList<Map<String,Object>>();for(var member:binding.topology().members()){var pos=new BlockPos(member.x(),member.y(),member.z());var be=s.level.getBlockEntity(pos);var observed=new TreeMap<String,Object>();observed.put("position",List.of(member.x(),member.y(),member.z()));observed.put("state",s.level.getBlockState(pos).toString());if(be instanceof RandomizableContainerBlockEntity c){observed.put("locked",c.isLocked());observed.put("loot_table",c.getLootTable()==null?null:c.getLootTable().identifier().toString());observed.put("slots",c.getContainerSize());observed.put("saved_nbt",c.saveWithFullMetadata(s.level.registryAccess()).toString());if(c.getLootTable()==null){var items=new ArrayList<Map<String,Object>>();for(int i=0;i<c.getContainerSize();i++){var stack=c.getItem(i);items.add(Map.of("index",i,"item",net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),"count",stack.getCount(),"max_stack",stack.isEmpty()?64:stack.getMaxStackSize()));}observed.put("items",items);}}nativeRows.add(observed);}row.put("native",nativeRows);row.put("integration_root",null);row.put("save_proof",null);try{Files.createDirectories(s.evidence);Files.writeString(s.evidence.resolve("adapter-observations.jsonl"),new com.google.gson.GsonBuilder().serializeNulls().create().toJson(row)+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);try(var channel=java.nio.channels.FileChannel.open(s.evidence.resolve("adapter-observations.jsonl"),StandardOpenOption.WRITE)){channel.force(true);}System.out.println("CC_D05_NATIVE_FRAME "+event);}catch(Exception e){throw new RuntimeException(e);}}
}
